 10→/**
 11→ * Factory for creating {@link JlsmTable} instances.
 12→ *
 13→ * <p>
 14→ * Provides static builder methods for string-keyed and long-keyed tables. Each builder accepts a
 15→ * typed LSM tree and an optional schema, then constructs the appropriate table implementation.
 16→ */
 17→public final class StandardJlsmTable {
 18→
 19→    private StandardJlsmTable() {
 20→    }
 21→
 22→    /**
 23→     * Returns a builder for a string-keyed {@link JlsmTable}.
 24→     *
 25→     * @return a builder; never null
 26→     */
 27→    public static StringKeyedBuilder stringKeyedBuilder() {
 28→        return new StringKeyedBuilder();
 29→    }
 30→
 31→    /**
 32→     * Returns a builder for a long-keyed {@link JlsmTable}.
 33→     *
 34→     * @return a builder; never null
 35→     */
 36→    public static LongKeyedBuilder longKeyedBuilder() {
 37→        return new LongKeyedBuilder();
 38→    }
 39→
 40→    // -------------------------------------------------------------------------
 41→    // StringKeyed builder
 42→    // -------------------------------------------------------------------------
 43→
 44→    /**
 45→     * Builder for {@link JlsmTable.StringKeyed} tables.
 46→     */
 47→    public static final class StringKeyedBuilder implements JlsmTable.StringKeyed.Builder {
 48→
 49→        private TypedLsmTree.StringKeyed<JlsmDocument> tree;
 50→        private JlsmSchema schema;
 51→
 52→        private StringKeyedBuilder() {
 53→        }
 54→
 55→        /**
 56→         * Sets the backing LSM tree.
 57→         *
 58→         * @param tree the string-keyed LSM tree; must not be null
 59→         * @return this builder
 60→         */
 61→        public StringKeyedBuilder lsmTree(TypedLsmTree.StringKeyed<JlsmDocument> tree) {
 62→            this.tree = Objects.requireNonNull(tree, "tree must not be null");
 63→            return this;
 64→        }
 65→
 66→        /**
 67→         * Sets the optional schema for write-time validation.
 68→         *
 69→         * @param schema the schema; may be null
 70→         * @return this builder
 71→         */
 72→        public StringKeyedBuilder schema(JlsmSchema schema) {
 73→            this.schema = schema;
 74→            return this;
 75→        }
 76→
 77→        @Override
 78→        public JlsmTable.StringKeyed build() {
 79→            Objects.requireNonNull(tree, "tree must not be null");
 80→            final MemorySerializer<JlsmDocument> codec = schema != null
 81→                    ? DocumentSerializer.forSchema(schema)
 82→                    : null;
 83→            assert codec != null : "codec must not be null when schema is provided";
 84→            return new StringKeyedTable(tree, codec, schema);
 85→        }
 86→    }
 87→
 88→    // -------------------------------------------------------------------------
 89→    // LongKeyed builder
 90→    // -------------------------------------------------------------------------
 91→
 92→    /**
 93→     * Builder for {@link JlsmTable.LongKeyed} tables.
 94→     */
 95→    public static final class LongKeyedBuilder implements JlsmTable.LongKeyed.Builder {
 96→
 97→        private TypedLsmTree.LongKeyed<JlsmDocument> tree;
 98→        private JlsmSchema schema;
 99→
100→        private LongKeyedBuilder() {
101→        }
102→
103→        /**
104→         * Sets the backing LSM tree.
105→         *
106→         * @param tree the long-keyed LSM tree; must not be null
107→         * @return this builder
108→         */
109→        public LongKeyedBuilder lsmTree(TypedLsmTree.LongKeyed<JlsmDocument> tree) {
110→            this.tree = Objects.requireNonNull(tree, "tree must not be null");
111→            return this;
112→        }
113→
114→        /**
115→         * Sets the optional schema for write-time validation.
116→         *
117→         * @param schema the schema; may be null
118→         * @return this builder
119→         */
120→        public LongKeyedBuilder schema(JlsmSchema schema) {
121→            this.schema = schema;
122→            return this;
123→        }
124→
125→        @Override
126→        public JlsmTable.LongKeyed build() {
127→            Objects.requireNonNull(tree, "tree must not be null");
128→            final MemorySerializer<JlsmDocument> codec = schema != null
129→                    ? DocumentSerializer.forSchema(schema)
130→                    : null;
131→            assert codec != null : "codec must not be null when schema is provided";
132→            return new LongKeyedTable(tree, codec, schema);
133→        }
134→    }
135→}
