 58→        return tree.get(key);
 59→    }
 60→
 61→    @Override
 62→    public void update(long key, JlsmDocument doc, UpdateMode mode) throws IOException {
 63→        Objects.requireNonNull(doc, "doc must not be null");
 64→        Objects.requireNonNull(mode, "mode must not be null");
 65→
 66→        final Optional<JlsmDocument> existing = tree.get(key);
 67→        if (existing.isEmpty()) {
 68→            throw new KeyNotFoundException(String.valueOf(key));
 69→        }
 70→
 71→        switch (mode) {
 72→            case REPLACE -> tree.put(key, doc);
 73→            case PATCH -> {
 74→                final JlsmDocument merged = mergeDocuments(existing.get(), doc);
 75→                tree.put(key, merged);
 76→            }
 77→        }
 78→    }
 79→
 80→    @Override
 81→    public void delete(long key) throws IOException {
 82→        tree.delete(key);
 83→    }
 84→
 85→    @Override
 86→    public Iterator<TableEntry<Long>> getAllInRange(long from, long to) throws IOException {
 87→        final Iterator<Entry> rawEntries = tree.scan(from, to);
 88→        return new Iterator<>() {
 89→            private TableEntry<Long> next;
 90→
 91→            {
 92→                advance();
 93→            }
 94→
 95→            private void advance() {
 96→                next = null;
 97→                while (rawEntries.hasNext()) {
 98→                    final Entry entry = rawEntries.next();
 99→                    if (entry instanceof Entry.Put put) {
100→                        final long decodedKey = decodeKey(entry.key());
101→                        final JlsmDocument doc = codec.deserialize(put.value());
102→                        next = new TableEntry<>(decodedKey, doc);
103→                        return;
104→                    }
105→                    // Skip Entry.Delete tombstones
106→                }
107→            }
108→
109→            @Override
110→            public boolean hasNext() {
111→                return next != null;
112→            }
113→
114→            @Override
115→            public TableEntry<Long> next() {
116→                if (next == null) {
117→                    throw new NoSuchElementException();
118→                }
119→                final TableEntry<Long> current = next;
120→                advance();
121→                return current;
122→            }
123→        };
124→    }
125→
126→    @Override
127→    public void close() throws IOException {
128→        tree.close();
129→    }
