133→    // -------------------------------------------------------------------------
134→
135→    /**
136→     * Decodes a long key from its sign-bit-flipped big-endian encoding.
137→     *
138→     * @param seg the encoded key segment; must be 8 bytes
139→     * @return the decoded long value
140→     */
141→    private static long decodeKey(MemorySegment seg) {
142→        final byte[] bytes = seg.toArray(ValueLayout.JAVA_BYTE);
143→        assert bytes.length == 8 : "long key segment must be 8 bytes";
144→        long v = 0L;
145→        for (final byte b : bytes) {
146→            v = (v << 8) | (b & 0xFFL);
147→        }
148→        return v ^ Long.MIN_VALUE;
149→    }
150→
151→    private static JlsmDocument mergeDocuments(JlsmDocument existing, JlsmDocument patch) {
152→        final Object[] existingVals = DocumentAccess.get().values(existing);
153→        final Object[] newVals = DocumentAccess.get().values(patch);
154→        assert existingVals.length == newVals.length
155→                : "existing and patch value arrays must have the same length";
156→        final Object[] merged = new Object[existingVals.length];
157→        for (int i = 0; i < merged.length; i++) {
158→            merged[i] = newVals[i] != null ? newVals[i] : existingVals[i];
159→        }
160→        return DocumentAccess.get().create(existing.schema(), merged);
161→    }
